/**
 * Unit tests for ParserBase._reportTooLongIntegral
 */
public class ParserBase__reportTooLongIntegral_TriageGen0Test {

    private ParserBase parserBase;
    private static final int NR_LONG = 1; // Assuming NR_LONG is defined in the context of the class
    private static final int NR_INT = 0;  // Assuming NR_INT/other is used for the else branch

    @Before
    public void setUp() {
        // ParserBase is abstract, so we must create a concrete subclass or a mock
        // Since we need to test protected methods and the method calls _reportError, 
        // spying on a mock is the most effective way to isolate the logic.
        IOContext iocontext = Mockito.mock(IOContext.class);
        parserBase = spy(new ParserBase(iocontext, 0) {
            @Override
            protected void _closeInput() throws IOException {}
            @Override
            protected void _releaseBuffers() throws IOException {}
            @Override
            protected void _handleEOF() throws com.fasterxml.jackson.core.JsonParseException {
                throw new com.fasterxml.jackson.core.JsonParseException(null, "EOF");
            }
        });
    }

    /**
     * Helper to invoke the protected method via reflection
     */
    private void invokeReportTooLongIntegral(int expType, String rawNum) throws Throwable {
        Method method = ParserBase.class.getDeclaredMethod("_reportTooLongIntegral", int.class, String.class);
        method.setAccessible(true);
        try {
            method.invoke(parserBase, expType, rawNum);
        } catch (java.lang.reflect.InvocationTargetException e) {
            throw e.getTargetException();
        }
    }

    /**
     * Test case for when the type is NR_LONG
     */
    @Test
    public void testReportTooLongIntegral_LongType() throws Throwable {
        int expType = NR_LONG;
        String rawNum = "9223372036854775808"; // Larger than Long.MAX_VALUE

        // We expect _reportError to be called with "long" in the message
        // Note: _longIntegerDesc is also called. Since it's a protected method in the same class,
        // we assume it returns a string representation of the number.

        invokeReportTooLongIntegral(expType, rawNum);

        // Verify _reportError is called with the correct type string
        // The pattern is "Numeric value (%s) out of range of %s"
        verify(parserBase)._reportError(
                eq("Numeric value (%s) out of range of %s"), 
                anyString(), 
                eq("long")
        );
    }

    /**
     * Test case for when the type is NOT NR_LONG (e.g., int)
     */
    @Test
    public void testReportTooLongIntegral_IntType() throws Throwable {
        int expType = NR_INT;
        String rawNum = "2147483648"; // Larger than Integer.MAX_VALUE

        invokeReportTooLongIntegral(expType, rawNum);

        // Verify _reportError is called with "int" in the message
        verify(parserBase)._reportError(
                eq("Numeric value (%s) out of range of %s"), 
                anyString(), 
                eq("int")
        );
    }
}
